"""Writing generated packages to disk.

Kept apart from the generators so that generation itself stays a pure function
of the configuration and can be tested without touching the filesystem.
"""

from __future__ import annotations

from collections.abc import Iterable, Sequence
from dataclasses import dataclass
from pathlib import Path

from .generator import GeneratedFile

#: First bytes of every generated file. Used to tell files this project owns
#: from anything a user has placed in the output directory by hand.
GENERATED_MARKER = "# Generated by hass-energy."


@dataclass(frozen=True)
class WriteResult:
    """What one write or check pass found."""

    written: tuple[Path, ...] = ()
    unchanged: tuple[Path, ...] = ()
    removed: tuple[Path, ...] = ()

    @property
    def changed(self) -> bool:
        """Whether the output directory differed from the generated packages."""

        return bool(self.written or self.removed)


def _obsolete(files: Sequence[GeneratedFile], output_dir: Path) -> list[Path]:
    """Generated files still on disk that the configuration no longer produces."""

    expected = {file.filename for file in files}
    obsolete = []
    for path in sorted(output_dir.glob("*.yaml")):
        if path.name in expected:
            continue
        if path.read_text(encoding="utf-8").startswith(GENERATED_MARKER):
            obsolete.append(path)
    return obsolete


def write_files(files: Iterable[GeneratedFile], output_dir: Path) -> WriteResult:
    """Write packages, leaving unchanged files untouched.

    Files whose content already matches are not rewritten, so their timestamps
    keep reflecting the last real change. Previously generated files the
    configuration no longer produces are removed.
    """

    files = list(files)
    output_dir.mkdir(parents=True, exist_ok=True)

    written: list[Path] = []
    unchanged: list[Path] = []
    for file in files:
        path = output_dir / file.filename
        if path.exists() and path.read_text(encoding="utf-8") == file.content:
            unchanged.append(path)
            continue
        path.write_text(file.content, encoding="utf-8")
        written.append(path)

    removed = _obsolete(files, output_dir)
    for path in removed:
        path.unlink()

    return WriteResult(tuple(written), tuple(unchanged), tuple(removed))


def check_files(files: Iterable[GeneratedFile], output_dir: Path) -> WriteResult:
    """Report what writing would change, without changing anything."""

    files = list(files)
    if not output_dir.exists():
        return WriteResult(written=tuple(output_dir / file.filename for file in files))

    stale: list[Path] = []
    unchanged: list[Path] = []
    for file in files:
        path = output_dir / file.filename
        if path.exists() and path.read_text(encoding="utf-8") == file.content:
            unchanged.append(path)
        else:
            stale.append(path)

    return WriteResult(tuple(stale), tuple(unchanged), tuple(_obsolete(files, output_dir)))
